146	    /**
147	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
148	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
149	     * syntactically valid address (rejecting anything else with 400).
150	     *
151	     * @param email the email value (may be {@code null})
152	     * @return the lower-cased email, or {@code null} if the input was {@code null}
153	     */
154	    private String normalizeEmail(String email) {
155	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
156	    }
157	
158	    /**
159	     * Builds the customer code '<LAST3>-<NNNN>' for a newly created owner, where LAST3 is the
160	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
161	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
162	     *
163	     * @param lastName the owner's last name
164	     * @return the formatted customer code
165	     */
166	    private String nextCustomerCode(String lastName) {
167	        String prefix = lastName.substring(0, Math.min(3, lastName.length()))
168	            .toUpperCase(java.util.Locale.ROOT);
169	        int sequence = this.clinicService.findAllOwners().size() + 1;
170	        return String.format("%s-%04d", prefix, sequence);
171	    }
172	
173	    /**
174	     * Determines whether the given normalized telephone is already used by an existing owner.
175	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
176	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
177	     * as the same number.
178	     *
179	     * @param normalizedTelephone the normalized (E.164) telephone to look for
180	     * @return {@code true} if another owner already uses this telephone
181	     */
182	    private boolean isTelephoneInUse(String normalizedTelephone) {
183	        if (normalizedTelephone == null) {
184	            return false;
185	        }
186	        return this.clinicService.findAllOwners().stream()
187	            .map(Owner::getTelephone)
188	            .map(telephoneNormalizer::normalize)
189	            .anyMatch(normalizedTelephone::equals);
190	    }
