192	    /**
193	     * Determines whether another owner already shares the given household, i.e. has the same last
194	     * name and the same address. Both fields are compared case-insensitively after collapsing runs
195	     * of whitespace to a single space and trimming, so values that differ only in letter case or in
196	     * incidental spacing are treated as the same household.
197	     *
198	     * @param lastName the last name of the owner being created
199	     * @param address  the address of the owner being created
200	     * @return {@code true} if an existing owner has a matching last name and address
201	     */
202	    private boolean isHouseholdInUse(String lastName, String address) {
203	        String normalizedLastName = normalizeForHousehold(lastName);
204	        String normalizedAddress = normalizeForHousehold(address);
205	        return this.clinicService.findAllOwners().stream()
206	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
207	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress));
208	    }
209	
210	    /**
211	     * Normalizes a value for household comparison by trimming, collapsing internal runs of
212	     * whitespace to a single space and lower-casing, so comparisons ignore case and incidental
213	     * whitespace differences.
214	     *
215	     * @param value the value to normalize (may be {@code null})
216	     * @return the normalized value, or the empty string if the input was {@code null}
217	     */
218	    private String normalizeForHousehold(String value) {
219	        if (value == null) {
220	            return "";
221	        }
222	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
223	    }
