227	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
228	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
229	        if (currentOwner == null) {
230	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	        }
232	        currentOwner.setAddress(ownerFieldsDto.getAddress());
233	        currentOwner.setCity(ownerFieldsDto.getCity());
234	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
235	        currentOwner.setLastName(ownerFieldsDto.getLastName());
236	        // Normalize the telephone to canonical E.164 form so it is stored and returned
237	        // consistently with create; an unformattable value is rejected with 400.
238	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
239	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
240	        this.clinicService.saveOwner(currentOwner);
241	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
242	    }
