247	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        this.clinicService.deleteOwner(owner);
253	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
254	    }
