256	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
257	    @Override
258	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
259	        Owner owner = this.clinicService.findOwnerById(ownerId);
260	        if (owner == null) {
261	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
262	        }
263	        HttpHeaders headers = new HttpHeaders();
264	        Pet pet = petMapper.toPet(petFieldsDto);
265	        owner.setId(ownerId);
266	        pet.setOwner(owner);
267	        pet.getType().setName(null);
268	        this.clinicService.savePet(pet);
269	        PetDto petDto = petMapper.toPetDto(pet);
270	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
271	            .buildAndExpand(pet.getId()).toUri());
272	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
273	    }
