275	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
276	    @Override
277	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
278	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
279	        if (currentOwner != null) {
280	            Pet currentPet = this.clinicService.findPetById(petId);
281	            if (currentPet != null) {
282	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
283	                currentPet.setName(petFieldsDto.getName());
284	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
285	                this.clinicService.savePet(currentPet);
286	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
287	            }
288	        }
289	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
290	    }
