292	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
293	    @Override
294	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
295	        HttpHeaders headers = new HttpHeaders();
296	        Visit visit = visitMapper.toVisit(visitFieldsDto);
297	        Pet pet = new Pet();
298	        pet.setId(petId);
299	        visit.setPet(pet);
300	        this.clinicService.saveVisit(visit);
301	        VisitDto visitDto = visitMapper.toVisitDto(visit);
302	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
303	            .buildAndExpand(visit.getId()).toUri());
304	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
305	    }
306	
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
310	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
311	        Owner owner = this.clinicService.findOwnerById(ownerId);
312	        if (owner != null) {
313	            Pet pet = owner.getPet(petId);
314	            if (pet != null) {
315	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
316	            }
317	        }
318	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
319	    }
